int rfcomm_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                   size_t size, int flags)
{
    struct sock *sk = sock->sk;
    int bytes_received;

    if (sk->sk_user_data && sk->sk_state == BT_CONNECTED) {
        /* Accept deferred RFCOMM connection setup if applicable */
        rfcomm_accept_connection(sk);
    }

    bytes_received = sock->ops->recvmsg(iocb, sock, msg, size, flags);

    if (bytes_received > 0) {
        sk->sk_rmem_alloc += bytes_received;
        sock_update_rmem(sk);
    }

    if (sk->sk_rmem_alloc < RFCOMM_RMEM_THRESHOLD) {
        rfcomm_unthrottle(sk);
    }

    return bytes_received;
}

