#include <linux/socket.h>
#include <linux/ioctl.h>
#include <linux/skbuff.h>

int rfcomm_sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    int len = 0;
    struct sock *sk = sock->sk;

    if (test_bit(SOCK_ASYNC_LINGER, &sk->sk_socket->flags)) {
        // Accept deferred RFCOMM connection setup
        clear_bit(SOCK_ASYNC_LINGER, &sk->sk_socket->flags);
    }

    // Call lower-level receive function
    len = sock->ops->recvmsg(iocb, sock, msg, size, flags);

    if (len > 0) {
        // Update socket's receive memory allocation
        sk->sk_rmem_alloc += len;

        // Check if memory usage is below a threshold to unthrottle
        if (sk->sk_rmem_alloc < sk->sk_rcvbuf / 2) {
            set_bit(SOCK_DEFERRED_RECV, &sk->sk_socket->flags);
        }
    }

    return len;
}
